// Stereo mixer: Two active inputs with separate gain and pan, plus master level.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  oscillator as oscillatorDefinition,
  mixer as mixerDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    low_waveform: {
      "path": "/primitives/mixer/low/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 0,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    low_frequency: {
      "path": "/primitives/mixer/low/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 110
    },
    low_level: {
      "path": "/primitives/mixer/low/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    high_waveform: {
      "path": "/primitives/mixer/high/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 1,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    high_frequency: {
      "path": "/primitives/mixer/high/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 330
    },
    high_level: {
      "path": "/primitives/mixer/high/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    mixer_masterLevel: {
      "path": "/primitives/mixer/mixer/0",
      "label": "Master level",
      "group": "Mixer",
      "min": 0,
      "max": 2,
      "default": 1
    },
    mixer_input1Gain: {
      "path": "/primitives/mixer/mixer/1",
      "label": "Input 1 gain",
      "group": "Mixer",
      "min": 0,
      "max": 2,
      "default": 1
    },
    mixer_input2Gain: {
      "path": "/primitives/mixer/mixer/2",
      "label": "Input 2 gain",
      "group": "Mixer",
      "min": 0,
      "max": 2,
      "default": 1
    },
    mixer_input1Pan: {
      "path": "/primitives/mixer/mixer/33",
      "label": "Input 1 pan",
      "group": "Mixer",
      "min": -1,
      "max": 1,
      "default": 0
    },
    mixer_input2Pan: {
      "path": "/primitives/mixer/mixer/34",
      "label": "Input 2 pan",
      "group": "Mixer",
      "min": -1,
      "max": 1,
      "default": 0
    },
  };

  // Audio inputs and outputs — generated sound; no audio input is needed.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const low = graph.add(oscillatorDefinition.type, {"id":4});
  graph.registerInstance('/primitives/mixer/low', low);
  low.parameter('waveform').expose(controls.low_waveform);
  low.parameter('frequency').expose(controls.low_frequency);
  low.parameter('level').expose(controls.low_level);

  const high = graph.add(oscillatorDefinition.type, {"id":5});
  graph.registerInstance('/primitives/mixer/high', high);
  high.parameter('waveform').expose(controls.high_waveform);
  high.parameter('frequency').expose(controls.high_frequency);
  high.parameter('level').expose(controls.high_level);

  const mixer = graph.add(mixerDefinition.type, {"id":6,"config":{"inputs":32}});
  graph.registerInstance('/primitives/mixer/mixer', mixer);
  mixer.parameter('masterLevel').expose(controls.mixer_masterLevel);
  mixer.parameter('input1Gain').expose(controls.mixer_input1Gain);
  mixer.parameter('input2Gain').expose(controls.mixer_input2Gain);
  mixer.parameter('input1Pan').expose(controls.mixer_input1Pan);
  mixer.parameter('input2Pan').expose(controls.mixer_input2Pan);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(low.output('out'), mixer.input('in-1'));
  graph.connect(high.output('out'), mixer.input('in-2'));
  graph.connect(mixer.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.low_waveform,
    controls.low_frequency,
    controls.low_level,
    controls.high_waveform,
    controls.high_frequency,
    controls.high_level,
    controls.mixer_masterLevel,
    controls.mixer_input1Gain,
    controls.mixer_input2Gain,
    controls.mixer_input1Pan,
    controls.mixer_input2Pan
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
